#include <string.h>

/**
 * @brief Reverses a null-terminated string in place.
 *
 * This function modifies the input string directly by swapping characters
 * from the beginning and the end until the middle of the string is reached.
 *
 * @param str A pointer to the null-terminated string to be reversed.
 */
void reverseStringInPlace(char *str) {
    if (str == NULL) {
        return; // Handle the case where the input pointer is NULL
    }

    // Initialize pointers: 'start' at the beginning, 'end' at the last character.
    int start = 0;
    int end = strlen(str) - 1;
    char temp;

    // Loop until the start pointer crosses or meets the end pointer
    while (start < end) {
        // 1. Store the character at the start position temporarily
        temp = str[start];

        // 2. Replace the character at the start with the character at the end
        str[start] = str[end];

        // 3. Replace the character at the end with the stored character (original start)
        str[end] = temp;

        // Move the pointers inward
        start++;
        end--;
    }
}

// --- Example Usage ---
